دالة بدل_المسافات(نص) {
    متغير ن = ""
    من_أجل (ع في نص) {
        إذا (ع == " ") {
            ن = ن + "_"
        } وإلا {
            ن = ن + ع
        }
    }
    ارجع ن
}
```

